// Opens bundles generated by wa-export via file:// in Chromium and WebKit and
// checks password, decryption, search, media, per-password isolation and CSP (no network).
// Usage: pnpm --filter export-shell test:e2e
const pw = require("playwright-core");
const OUT = process.argv[2];
let failed = 0;
const results = [];
const check = (name, ok, extra = "") => (ok || failed++, results.push(`${ok ? "OK  " : "FAIL"} ${name}${extra ? " — " + extra : ""}`));

async function openPkg(browser, pkg) {
  // Forces Portuguese: the checks look for the UI texts in pt-BR.
  const page = await browser.newPage({ viewport: { width: 1200, height: 800 }, locale: "pt-BR" });
  const problems = [];
  page.on("request", (r) => { if (!r.url().startsWith("file:") && !r.url().startsWith("blob:") && !r.url().startsWith("data:")) problems.push("NETWORK " + r.url()); });
  page.on("console", (m) => { if (m.type() === "error" || /Content Security Policy|Refused/i.test(m.text())) problems.push("CONSOLE " + m.text()); });
  page.on("pageerror", (e) => problems.push("ERROR " + e.message));
  await page.goto(`file://${OUT}/${pkg}/index.html`);
  return { page, problems };
}

async function unlock(page, password) {
  await page.fill("input[type=password]", password);
  await page.click("button.primary");
}

(async () => {
  for (const [bname, btype] of [["chromium", pw.chromium], ["webkit", pw.webkit]]) {
    const browser = await btype.launch();

    // 1) Encrypted media
    {
      const { page, problems } = await openPkg(browser, "cifrado");
      await page.waitForSelector("input[type=password]");
      await unlock(page, "some wrong password");
      const wrong = await page.waitForSelector("text=Senha incorreta", { timeout: 30000 }).then(() => true, () => false);
      check(`${bname}: wrong password rejected`, wrong);
      const t0 = Date.now();
      await unlock(page, "senha do export");
      await page.waitForSelector(".chat-item", { timeout: 30000 });
      const argonMs = Date.now() - t0;
      const chats = await page.locator(".chat-item").count();
      const archived = await page.locator(".archived-row").count();
      check(`${bname}: chats unlocked`, chats + archived >= 2, `${chats} in the list + archived, Argon2id ~${argonMs} ms`);
      await page.click(".chat-item >> nth=0");
      const text = await page.waitForSelector("text=Vamos tomar um café", { timeout: 15000 }).then(() => true, () => false);
      check(`${bname}: decrypted message shows up`, text);
      await page.fill(".search-box input", "CAFE");
      const hit = await page.waitForSelector(".search-hit mark", { timeout: 10000 }).then(async (el) => await el.textContent(), () => null);
      check(`${bname}: accent-insensitive search highlights the term`, hit === "café", `marked: ${hit}`);
      await page.fill(".search-box input", "");
      const banner = await page.locator(".folder-banner").count();
      check(`${bname}: asks for the media folder`, banner === 1);
      let folderOk = false;
      try {
        await page.setInputFiles("input[type=file]", `${OUT}/cifrado`);
        folderOk = true;
      } catch (e) {
        check(`${bname}: folder selection via Playwright`, false, String(e.message).split("\n")[0]);
      }
      if (folderOk) {
        await page.click(".chat-item >> nth=0");
        const full = await page.waitForSelector(".visual img.full.loaded", { timeout: 15000 }).then(() => true, () => false);
        check(`${bname}: photo decrypted in the browser`, full);
        await page.screenshot({ path: `${OUT}/${bname}-cifrado.png` });
        await page.click(".visual.clickable");
        const lb = await page.waitForSelector(".lightbox img", { timeout: 10000 }).then(() => true, () => false);
        check(`${bname}: fullscreen opens the photo`, lb);
        await page.keyboard.press("Escape");
      }
      check(`${bname}: no network, no CSP violation, no errors`, problems.length === 0, problems.slice(0, 3).join(" | "));
      await page.close();
    }

    // 2) Plain (unencrypted) media
    {
      const { page, problems } = await openPkg(browser, "claro");
      await page.waitForSelector("input[type=password]");
      await unlock(page, "senha do export");
      await page.waitForSelector(".chat-item", { timeout: 30000 });
      await page.click(".chat-item >> nth=0");
      const full = await page.waitForSelector(".visual img.full.loaded", { timeout: 15000 }).then(() => true, () => false);
      check(`${bname}: plain photo without picking a folder`, full);
      check(`${bname}: (plain) no network/CSP/errors`, problems.length === 0, problems.slice(0, 3).join(" | "));
      await page.close();
    }

    // 3) One password per chat
    {
      const { page, problems } = await openPkg(browser, "por-conversa");
      await page.waitForSelector("input[type=password]");
      await unlock(page, "senha da alice");
      await page.waitForSelector(".chat-item", { timeout: 30000 });
      const a = (await page.locator(".chat-item").count()) + (await page.locator(".archived-row").count());
      await page.fill(".search-box input", "grupo");
      await page.waitForTimeout(800);
      const leaked = await page.locator(".search-hit").count();
      await page.fill(".search-box input", "");
      check(`${bname}: password A unlocks only chat A`, a === 1, `items=${a}`);
      check(`${bname}: search with A doesn't find B's text`, leaked === 0);
      await page.click("button[title^='Liberar mais']");
      await unlock(page, "senha do grupo");
      await page.waitForSelector(".archived-row", { timeout: 30000 });
      await page.fill(".search-box input", "grupo");
      const found = await page.waitForSelector(".search-hit", { timeout: 10000 }).then(() => true, () => false);
      check(`${bname}: with password B, search covers both`, found);
      check(`${bname}: (per chat) no network/CSP/errors`, problems.length === 0, problems.slice(0, 3).join(" | "));
      await page.close();
    }

    // 4) Language switch on the password screen (only in the page's memory)
    {
      const { page, problems } = await openPkg(browser, "cifrado");
      await page.waitForSelector("input[type=password]");
      await page.click(".unlock-lang .lang-trigger");
      await page.click(".lang-option:has-text('English')");
      const en = await page.waitForSelector("text=This history is encrypted", { timeout: 5000 }).then(() => true, () => false);
      await unlock(page, "some wrong password");
      const wrong = await page.waitForSelector("text=Wrong password", { timeout: 30000 }).then(() => true, () => false);
      check(`${bname}: password screen in English`, en && wrong);
      check(`${bname}: (language) no network/CSP/errors`, problems.length === 0, problems.slice(0, 3).join(" | "));
      await page.close();
    }
    await browser.close();
  }
  // No remote resource, even when requested by the page's own script.
  for (const [bname, btype] of [["chromium", pw.chromium], ["webkit", pw.webkit]]) {
    const browser = await btype.launch();
    const page = await browser.newPage();
    const net = [];
    page.on("response", (r) => r.url().startsWith("http") && net.push(r.url()));
    await page.goto(`file://${OUT}/cifrado/index.html`);
    await page.waitForSelector("input[type=password]");
    // As a file (file:), which the CSP allows; inline would be blocked and the test would prove nothing.
    // Chromium reports the CSP violation caused by the probe as an error here.
    let blocked = "";
    await page
      .addScriptTag({ url: "file://" + require("path").join(__dirname, "probe.js") })
      .catch((e) => (blocked = /Content Security Policy/.test(e.message) ? "CSP blocked the remote script" : e.message));
    await page.waitForTimeout(1500);
    const ran = await page.evaluate(() => document.documentElement.dataset.probe === "ran");
    check(`${bname}: probe ran in the page and no response came from the network`, ran && net.length === 0, `ran=${ran} ${blocked} ${net.join(", ")}`.trim());
    await browser.close();
  }
  console.log(results.join("\n"));
  if (failed) process.exit(1);
})().catch((e) => { console.error(e); process.exit(1); });
